macro_rules! name_for_constructor_search {
    () => {
        # [doc = " Returns `Some` if the cursor is at a position where we should search for constructor/initialization usages."] # [doc = " This is used to implement the special constructor search behavior when the cursor is on specific tokens"] # [doc = " in a struct/enum/variant definition."] # [doc = ""] # [doc = " # Returns"] # [doc = " - `Some(name)` if the cursor is on:"] # [doc = "   - `{` after a struct/enum/variant definition"] # [doc = "   - `(` for tuple structs/variants"] # [doc = "   - `;` for unit structs"] # [doc = "   - The type name in a struct/enum/variant definition"] # [doc = " - `None` otherwise"] # [doc = ""] # [doc = " The returned name is the name of the type whose constructor usages should be searched for."] fn name_for_constructor_search (syntax : & SyntaxNode , position : FilePosition) -> Option < ast :: Name > { let token = syntax . token_at_offset (position . offset) . right_biased () ? ; let token_parent = token . parent () ? ; let kind = token . kind () ; if kind == T ! [;] { ast :: Struct :: cast (token_parent) . filter (| struct_ | struct_ . field_list () . is_none ()) . and_then (| struct_ | struct_ . name ()) } else if kind == T ! ['{'] { match_ast ! { match token_parent { ast :: RecordFieldList (rfl) => match_ast ! { match (rfl . syntax () . parent () ?) { ast :: Variant (it) => it . name () , ast :: Struct (it) => it . name () , ast :: Union (it) => it . name () , _ => None , } } , ast :: VariantList (vl) => ast :: Enum :: cast (vl . syntax () . parent () ?) ?. name () , _ => None , } } } else if kind == T ! ['('] { let tfl = ast :: TupleFieldList :: cast (token_parent) ? ; match_ast ! { match (tfl . syntax () . parent () ?) { ast :: Variant (it) => it . name () , ast :: Struct (it) => it . name () , _ => None , } } } else { None } }
    };
}

name_for_constructor_search!();